/**
 * Request body hints for the Body tab, from Okta's OpenAPI spec (generated by
 * `npm run bodies`): the body's fields, which required ones the JSON is missing,
 * and the spec's request examples. Each API area's bodies are a separate file,
 * loaded only when the Body tab asks for one of its endpoints.
 */
import type { Endpoint } from './suggest';

export interface BodyField {
  /** Dotted path; `[]` steps into an array's items, e.g. `groupIds[]`, `roles[].type`. */
  p: string;
  /** JSON type, `[]` for arrays, e.g. `string`, `object`, `string[]`. */
  t: string;
  /** Required (when its parent object is there). */
  r?: 1;
  /** Short description. */
  d?: string;
  /** Allowed values. */
  e?: string[];
}

export interface BodyExample {
  n: string;
  v: unknown;
}

export interface BodySchema {
  f: BodyField[];
  x?: BodyExample[];
}

type Chunk = Record<string, BodySchema>;

const chunks = import.meta.glob<Chunk>('./bodies/*.json', { import: 'default' });
const loading = new Map<string, Promise<Chunk | undefined>>();

const chunkName = (tag: string) => `./bodies/${tag.replace(/[^\w-]/g, '_')}.json`;

/** The body schema of `endpoint`, or undefined if the spec gives it no JSON body. */
export async function loadBodySchema(endpoint: Endpoint): Promise<BodySchema | undefined> {
  const name = chunkName(endpoint.t);
  let chunk = loading.get(name);
  if (!chunk) {
    const load = chunks[name];
    chunk = load ? load().catch(() => undefined) : Promise.resolve(undefined);
    loading.set(name, chunk);
  }
  return (await chunk)?.[`${endpoint.m} ${endpoint.p}`];
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/**
 * The values at `path` in `body`, one per array item that `[]` steps into.
 * A missing step yields nothing, so fields under an absent parent aren't checked.
 */
function valuesAt(body: unknown, path: string): unknown[] {
  let values = [body];
  const steps = path.split('.');
  for (const [i, step] of steps.entries()) {
    const array = step.endsWith('[]');
    const key = array ? step.slice(0, -2) : step;
    const last = i === steps.length - 1;
    values = values.flatMap((v) => {
      if (!isObject(v) || !(key in v)) return last ? [undefined] : [];
      const value = v[key];
      if (!array || last) return [value];
      return Array.isArray(value) ? value : [];
    });
  }
  return values;
}

/** The parent path of a field, e.g. `profile` for `profile.login`, `roles` for `roles[].type`. */
const parentOf = (path: string) => path.slice(0, Math.max(path.lastIndexOf('.'), 0));

/**
 * Required fields missing from `body`. A field nested under an object is only
 * required once that object is there, and under an array, in each of its items.
 */
export function missingFields(fields: BodyField[], body: unknown): BodyField[] {
  return fields.filter((field) => {
    if (!field.r) return false;
    const parent = parentOf(field.p);
    if (parent && !hasValue(body, parent.replace(/\[\]$/, ''))) return false;
    return valuesAt(body, field.p).some((v) => v === undefined);
  });
}

function hasValue(body: unknown, path: string) {
  return valuesAt(body, path).some((v) => v !== undefined && v !== null);
}

/** The fields `body` sets, by path. */
export function presentFields(fields: BodyField[], body: unknown): Set<string> {
  return new Set(fields.filter((f) => hasValue(body, f.p)).map((f) => f.p));
}

const placeholder = (field: BodyField): unknown => {
  if (field.t.endsWith('[]')) return [];
  if (field.e?.length) return field.e[0];
  switch (field.t) {
    case 'object':
      return {};
    case 'integer':
    case 'number':
      return 0;
    case 'boolean':
      return false;
    default:
      return '';
  }
};

/**
 * A starter body when the spec has no examples: each required field (and the
 * required fields of required objects) with a placeholder value.
 */
export function skeleton(fields: BodyField[]): Record<string, unknown> {
  const body: Record<string, unknown> = {};
  const byPath = new Map(fields.map((f) => [f.p, f]));
  for (const field of fields) {
    if (!field.r || field.p.includes('[]')) continue;
    const steps = field.p.split('.');
    // Every object above it must be required too.
    const chain = steps.map((_, i) => byPath.get(steps.slice(0, i + 1).join('.')));
    if (chain.some((f) => !f?.r)) continue;
    let target = body;
    for (const step of steps.slice(0, -1)) {
      const next = target[step];
      if (!isObject(next)) target[step] = {};
      target = target[step] as Record<string, unknown>;
    }
    const key = steps[steps.length - 1]!;
    if (!(key in target)) target[key] = placeholder(field);
  }
  return body;
}

/** The body to insert for an example (or the skeleton), as formatted JSON. */
export const exampleBody = (value: unknown) => JSON.stringify(value, null, 2);
